We begin by defining \emph{horns}. For each $n \ge 1$ and $0 \le j \le n$, the \textbf{$j$-th horn} $\Lambda^n_j$ is a subcomplex of the standard $n$-simplex $\Delta^n$ defined by
\[
(\Lambda^n_j)_k = \{ f : [k] \to [n] \mid [n] \setminus \{ j \} \not\subset f([k]) \}.
\]
In other words, $\Lambda^n_j$ is the union of all $(n-1)$-dimensional faces of $\Delta^n$ except the $j$-th face:
\[
\Lambda^n_j = \bigcup_{i \neq j} \Delta^{[n] \setminus \{i\}} \subset \Delta^n.
\]
When $0 < j < n$, the horn $\Lambda^n_j \subset \Delta^n$ is called an \textbf{inner horn}.

A \textbf{quasi-category} is a simplicial set $C$ such that, for every map $f : \Lambda^n_j \to C$ from an inner horn, there exists its extension $g : \Delta^n \to C$. That is, $C$ is a quasi-category if the restriction map:
\[
\operatorname{Hom}(\Delta^n, C) \to \operatorname{Hom}(\Lambda^n_j, C)
\]
induced by inclusion $\Lambda^n_j \hookrightarrow \Delta^n$ is surjective for all $n \ge 2$ and $0 < j < n$. In other words, there always exists a dotted arrow completing the following commutative diagram.



\begin{center}
\begin{tikzpicture}[auto]
\node (a) at (0, 1.2) {$\Lambda^n_j$};
\node (x) at (3.2, 1.2) {$C$};
\node (b) at (0, 0) {$\Delta^n$};  
\draw[->] (a) to node {} (x);
\draw[>->] (a) to node {} (b);
\draw[->, dashed] (b) to node[swap] {} (x);
\end{tikzpicture}
\end{center}

We now define the notion of a 2-crossed module. Our definition differs slightly from that given in \cite{MartinsPicken2011}. In particular, we use the notation ${}^a b$ for the right action, instead of writing it as  $a \triangleright b$.



A \textbf{2-crossed module} is given by a complex of groups:
\[
L \xrightarrow{\partial} H \xrightarrow{\partial} G 
\]
together with the following three structures:
\begin{itemize}
  \item a left action of $G$ by automorphisms on both $H$ and $L$ (with the action on $G$ given by conjugation);
  \item a left action of $H$ by automorphisms on $L$ (with the action on $H$ also given by conjugation); and
  \item a function $\{-,-\} : H \times H \rightarrow L$ (called the Peiffer lifting);
\end{itemize}
which are required to satisfy the following ten axioms:
\begin{enumerate}
  \item  $\partial\circ \partial =0$;
  \item  $\partial(^gh)= {^g}\partial(h),\ \partial({^g}l)= {^g}\partial(l),\ \partial(^hl)= {^h}\partial(l)$, for each $g \in G$, $h \in H$, and $l \in L$;
  \item  $^g \{h_2,h_1\} = \{\act{g} h_2, \act{g}h_1\}$, for each $g\in G$ and $h_1,h_2 \in H$;
  \label{pfeq}
  \item $\partial  \{h_2, h_1\} = h_2 h_1 h_2^{-1} \act{\partial h_2}h_1^{-1}$, for each $h_1,h_2 \in H$;
  \item $\act{\del l}l' = l l' l^{-1}$, for each $l,l' \in L$;
\label{2cm_pf_id}
  \item $\{\partial l_2,\partial l_1\} = l_2l_1l_2^{-1}l_1^{-1}$, for each $l_1,l_2 \in L$;
\label{2cm_not_need_pl}
  \item $\{h_3h_2,h_1\}={^{h_3}}\{h_2, h_1\}\{h_3, {^{\partial h_2}}h_1 \}$, for each $h_1,h_2, h_3 \in H$;
  \label{lpl}
  \item $\{h_3,h_2 h_1\}=\{h_3, h_2\} {^{(^{\partial h_3} h_2)}}\{h_3, h_1\}$, for each $h_1,h_2, h_3 \in H$;
  \label{rpl}
  \item ${^h}l = l\{\partial l^{-1}, h \}$, for each $h \in H$, and $l\in L$;
  \label{acthl}
  \item ${^{\partial h}}l = {^h}l\{h, \partial l^{-1} \}$, for each $h\in H$, and $l \in L$; and
  \label{actgl}
  \item $l^{-1} {^{\partial h}}l=\{\partial l^{-1}, h \}\{h, \partial l^{-1} \}$, for each $h \in H$, and $l \in L$.
  \label{2cm_not_need}
\end{enumerate}

\begin{rem}
In our context of 2-crossed modules, property \ref{2cm_not_need} follows from properties \ref{acthl} and \ref{actgl}. Similarly, property \ref{2cm_not_need_pl} can be derived by applying properties \ref{2cm_pf_id} and \ref{acthl} to the expression $\act{\del l_2}l_1$. We include these properties explicitly to emphasize that our structure satisfies the same axioms as standard 2-crossed modules.
\end{rem}

\label{sec-2-crossed module and sset}
Before presenting the definition of 3-crossed modules and proving that the simplicial set associated with a 3-crossed module is a quasi-category, we construct a simplicial set using a 2-crossed module and show that it is a quasi-category. Most of the discussion in this section serves as a simplified case of the 3-crossed module.

Let $W \coloneqq (L \xrightarrow{\partial} H \xrightarrow{\partial} G,\{-,-\} )$ be a 2-crossed module. We construct a simplicial set $M_W$ by the following data:

\begin{itemize}
    \item For each $[n] \in \Delta$, the set $M_W([n])$ consists of all the tuples $(g(-,-), h(-,-,-), l(-,$ $-,-,-))$, where:
    \begin{enumerate}
        \item $g: [n] \times_{\le} [n] \to G$ is a function assigning each ordered pair in $[n]$ to an element of $G$;
        \item $h:[n] \times_{\le} [n] \times_{\le} [n] \to H$ is a function assigning  each ordered triple in $[n]$ to an element of $H$; and
        \item $l: [n] \times_{\le} [n] \times_{\le} [n] \times_{\le} [n] \to L$ is a function assigning each ordered quadruple in $[n]$ to an element of $L$;
    \end{enumerate}
    and the three fuctions $g,h$ and $l$ satisfy the following conditions:
    
	
\begin{enumerate}[label=(\alph*)]
\item for each $i \le j \le k$ in $[n]$, we have the idenntity 
\begin{equation}
g_{ik} = \partial(h_{ijk})g_{jk}g_{ij};
\label{r2-simplex}
\end{equation}
\item for each $i \le j \le k \le m$ in $[n]$, we have the idenntity 
\begin{equation}
\partial (l_{ijkm})  h_{ikm}{^{g_{km}}}h_{ijk} = h_{ijm}h_{jkm};
\label{r3-simplex}
\end{equation}
\item for each $i \le j \le k \le m \le p$ in $[n]$, we have the idenntity 
\begin{equation}
 {^{h_{ijp}}}l_{jkmp}l_{ijmp}{^{h_{imp}}}\left({^{g_{mp}}}l_{ijkm}\right) = l_{ijkp}{^{h_{ikp}}}\{h_{kmp},{^{g_{mp}g_{km}}}h_{ijk} \}^{-1}l_{ikmp};
\label{r4-simplex}
\end{equation}
 \item for each $i \in [n]$, we have $g_{ii} = e_G$;
        
 \item for each $i \le j$ in $[n]$, we have $h_{iij} = h_{ijj} = e_H$; and
        
 \item for each $i \le j \le k$ in $[n]$, we have $l_{iijk} = l_{ijjk} = l_{ijkk} = e_L$.
    \end{enumerate}
    
    Here, we simply denote  $g(i,j)$, $h(i,j,k)$, and $l(i,j,k,m)$ by $g_{ij}$, $h_{ijk}$, and $l_{ijkm}$, respectively.
    
\item For a simplicial operater $\delta : [m] \rightarrow [n]$, we define $M_W(\delta): (M_W)_n \rightarrow (M_W)_m$ as follows: for each $(g,h,l) \in (M_W)_n$, 
\[
M_W(\delta)
\begin{pmatrix}
g(-,-)\\
h(-,-,-)\\
l(-,-,-,-)\\
\end{pmatrix}
\coloneqq
\begin{pmatrix}
g(\delta(-),\delta(-))\\
h(\delta(-),\delta(-),\delta(-))\\
l(\delta(-),\delta(-),\delta(-),\delta(-))\\
\end{pmatrix}
.\]
\end{itemize}

\noindent
We will show that simplicial set $M_W$ is a quasi-category in the following theorem.

\begin{theorem}\label{2cm and qusi}
Let $W \coloneqq (L \xrightarrow{\partial} H \xrightarrow{\partial} G,\{-,-\} )$ be a 2-crossed module. Then the simplicial set $M_W$ is a quasi-category.
\end{theorem}


In order to prove Theorem~\ref{2cm and qusi}, we need the following two lemmas.

\begin{lemma}
\label{lemma1}
Let \( W \coloneqq (L \xrightarrow{\partial} H \xrightarrow{\partial} G, \{-,-\}) \) be a 2-crossed module. For any \( n \ge 1 \) and any inner horn \( \Lambda^n_j \), let \( \phi \in \operatorname{Hom}(\Lambda^n_j, M_W) \). Then, for any \( m \ge 1 \) and any \( f \in (\Lambda^n_j)_m \), the following identity holds:
\[
\phi_m(f) 
\coloneqq
\begin{pmatrix}
\phi^g_m(f)(-,-) \\
\phi^h_m(f)(-,-,-) \\
\phi^l_m(f)(-,-,-,-)
\end{pmatrix}
=
\begin{pmatrix}
\phi^g_1(f(-,-))(0,1) \\
\phi^h_2(f(-,-,-))(0,1,2) \\
\phi^l_3(f(-,-,-,-))(0,1,2,3)
\end{pmatrix}.
\]
\end{lemma}

For any $m\ge 1$, any $k+1$ integers  \( 0\le x_0 \le x_1 \le \dots \le x_k \le m\)
and
each \( f \in (\Lambda^n_j)_m \),
clearly there exists a function \(f' \in (\Lambda^n_j)_k \) 
satisfying $f'(i) = f(x_i)$ for each $i$, $0\leq i\leq k$.
We renamed such a function $f'$ to  \( f(x_0, x_1, \dots, x_k) \in (\Lambda^n_j)_k \) 
for improving readability.

\begin{proof}
We will prove the case of \( \phi^l_m(f)(i,j,k,p) = \phi^l_3(f(i,j,k,p))(0,1,2,3) \). The other components \( \phi^g_m \) and \( \phi^h_m \) can be handled in the same way.

Let \( \phi \in \operatorname{Hom}(\Lambda^n_j, M_W) \) and let \( f \in (\Lambda^n_j)_m \) for \( m \ge 1 \). We consider \( \phi^l_m(f)(i,j,k,p) \) for \( i \le j \le k \le p \) in \( [m] \).

Define a function \( \langle ijkp \rangle : [3] \to [m] \) by:
\[
\langle ijkp \rangle(x) \coloneqq
\begin{cases}
i & \text{if } x = 0, \\
j & \text{if } x = 1, \\
k & \text{if } x = 2, \\
p & \text{if } x = 3.
\end{cases}
\]
Using the defining property of a natural transformation $\phi$, we obtain the following commutative diagram:
\begin{center}
\begin{tikzpicture}[scale=4] 
       \coordinate (0) at (0,0); 
 	\coordinate (1) at (1,0); 
	 \coordinate (2) at (0,-1);
	 \coordinate (3) at (1,-1);
	 \draw (0) node[] {$(\Lambda^n_j)_m$};
	 \draw (1) node[] {$(M_W)_m$};
	 \draw (2) node[] {$(\Lambda^n_j)_3$};
	 \draw (3) node[] {$(M_W)_3$};
 \draw[->]  ($(0)+(0.2,0)$) to  ($(1)+(-0.2,0)$);
  \draw[->]  ($(2)+(0.2,0)$) to ($(3)+(-0.2,0)$);
  \draw[->]  ($(0)+(0,-0.2)$) to ($(2)+(0,0.2)$);
\draw[->]  ($(1)+(0,-0.2)$) to ($(3)+(0,0.2)$);
 \draw (0.5,0) node[above] {$\phi_m$};  
 \draw (0.5,-1) node[below] {$\phi_3$};
 \draw (0,-0.5) node[left] {$(\Lambda^n_j)(\langle ijkp\rangle)$};
 \draw (1,-0.5) node[right] {$M_W(\langle ijkp\rangle)$};
 \draw[<-] (0.6,-0.5) arc[start angle=0, end angle=-270, radius=0.1];
\end{tikzpicture}
\end{center}
	 

From this diagram, we obtain
\begin{align*}
\phi^l_m(f)(i,j,k,p) 
&= \left(M_W(\langle ijkp \rangle)\left(\phi_m (f)\right)\right)(0,1,2,3) \\
&= \left( \phi_3\left(\Lambda^n_j (\langle ijkp\rangle)(f) \right) \right)(0,1,2,3) \\
&= \phi^l_3 (\langle f(i)f(j)f(k)f(p) \rangle)(0,1,2,3) .
\end{align*}
This completes the proof.
\end{proof}

By examining the proof above, we observe that the argument does not depend on the fact that we are using an inner horn \( \Lambda^n_j \). The same reasoning applies when \( \Lambda^n_j \) is replaced by the standard simplex \( \Delta^n \). For this reason, we obtain the following corollary.

\begin{corollary}
Let \( W \coloneqq (L \xrightarrow{\partial} H \xrightarrow{\partial} G, \{-,-\}) \) be a 2-crossed module. For any \( n \ge 1 \) and any standard simplex \( \Delta^n \), let \( \phi \in \operatorname{Hom}( \Delta^n, M_W) \). Then, for any \( m \ge 1 \) and any \( f \in (\Delta^n)_m \), the following identity holds:
\[
\phi_m(f) 
\coloneqq
\begin{pmatrix}
\phi^g_m(f)(-,-) \\
\phi^h_m(f)(-,-,-) \\
\phi^l_m(f)(-,-,-,-)
\end{pmatrix}
=
\begin{pmatrix}
\phi^g_1(f(-,-))(0,1) \\
\phi^h_2(f(-,-,-))(0,1,2) \\
\phi^l_3(f(-,-,-,-))(0,1,2,3)
\end{pmatrix}.
\]
\end{corollary}

By using Lemma~\ref{lemma1}, we can conclude that any $\phi \in \operatorname{Hom}(\Lambda^n_j, M_W)$ is determined by $\phi_1, \phi_2$, and $\phi_3$.
Let $\psi \in \operatorname{Hom}(\Lambda^2_1, M_W)$. Then, it is possible that $\psi^l_3(\langle 0111 \rangle)(0,1,2,3)$ occurs, by Lemma~\ref{lemma1}.
However, we want $\psi$ to be determined solely by $\psi_1$, since $\Lambda^2_1$ contains only 1-simplices.

The following lemma resolves the issue that arises when degenerate simplices are involved.

\begin{lemma}
\label{lemma2}

Let \( W \coloneqq (L \xrightarrow{\partial} H \xrightarrow{\partial} G, \{-,-\}) \) be a 2-crossed module. For any \( n \ge 1 \) and any inner horn \( \Lambda^n_j \), let \( \phi \in \operatorname{Hom}(\Lambda^n_j, M_W) \). Then for any map $ \langle a_0 \dots a_i a_{i+1}\dots a_m  \rangle \in (\Lambda^n_j)_m $ with \(1\le m \le 3 \), the following equation holds whenever $a_i = a_{i+1}$ for any $0\le i  \le m-1$:
\[
\phi_m (\langle a_0 \dots a_i a_{i+1}\dots a_m \rangle) (0,1,\dots, m) = \phi_{m-1} (\langle a_0 \dots a_i \hat{a}_{i+1}\dots a_m \rangle) (0,1,\dots, i,i,\dots,m-1)
\]
where the $\hat{a}_{i+1}$ indicates that ${a}_{i+1}$ omitted.

\end{lemma}

\begin{proof}
This follows directly from Lemma~\ref{lemma1}.
\end{proof}


Now we can prove Theorem~\ref{2cm and qusi}.

\begin{proof}[of Theorem~\ref{2cm and qusi}]
What we need to prove is that every \( \psi \in \operatorname{Hom}(\Lambda^n_j, M_W) \) can be extended to  
\( \tilde{\psi} \in \operatorname{Hom}(\Delta^n, M_W) \) for all \( n \geq 2 \) and \( 0 < j < n \).  
By using Lemmas~\ref{lemma1} and~\ref{lemma2}, and properties (d)–(e) of \( M_W \),  
to determine \( \tilde{\psi} \in \operatorname{Hom}(\Delta^n, M_W) \),  
it suffices to construct  
$
\tilde{\psi}_2(\langle ij \rangle)(0,1), \ 
\tilde{\psi}_3(\langle ijk \rangle)(0,1,2), \quad \text{and} \ 
\tilde{\psi}_4(\langle ijkp \rangle)(0,1,2,3)
$
for each \( 0 \leq i \leq j \leq k \leq p \leq n \).  
There are four cases to consider.


\begin{enumerate}
\item ${\rm Hom}(\Lambda^2_1, M_W)$ to ${\rm Hom}(\Delta^2, M_W)$

The images of $\Lambda^2_1$  and $\Delta^2$ are illstrated in Figrue~\ref{fig:l^2_1}.




For any \( \psi \in \operatorname{Hom}(\Lambda^2_1, M_W) \), the map \( \psi \) is determined by  
\( \psi_1(\langle 01 \rangle)(0,1) \) and \( \psi_1(\langle 12 \rangle)(0,1) \).
To extend \( \psi \) to \( \tilde{\psi} \in \operatorname{Hom}(\Delta^2, M_W) \),  
it suffices to construct  
\( \tilde{\psi}_1(\langle 02 \rangle)(0,1) \) and \( \tilde{\psi}_2(\langle 012 \rangle)(0,1,2) \).
We construct these as follows:  
\begin{align*}
\tilde{\psi}_1(\langle 01 \rangle)(0,1) &\coloneqq {\psi}_1(\langle 01 \rangle)(0,1)\\
\tilde{\psi}_1(\langle 12 \rangle)(0,1) &\coloneqq {\psi}_1(\langle 12 \rangle)(0,1)\\
\tilde{\psi}_1(\langle 02 \rangle)(0,1) &\coloneqq \psi_1(\langle 12\rangle)(0,1)\cdot \psi_1(\langle 01\rangle)(0,1)\\
\tilde{\psi}_2(\langle 012 \rangle)(0,1,2) &\coloneqq e_H
.
\end{align*}
It is easy to see that \( \tilde{\psi} \) is an element of \( \operatorname{Hom}(\Delta^2, M_W) \).


\item ${\rm Hom}(\Lambda^3_i, M_W)$ to ${\rm Hom}(\Delta^3, M_W)$ for $1 \le i \le 2$

We will prove the case \( i = 2 \). The case \( i = 1 \) can be handled in a similar manner.
By comparing \( \Lambda^3_2 \) and \( \Delta^3 \), the difference lies in the presence of the 2-simplex \( \langle 013 \rangle \) and the 3-simplex \( \langle 0123 \rangle \).  
To extend a map \( \psi \in \operatorname{Hom}(\Lambda^3_2, M_W) \) to  
\( \tilde{\psi} \in \operatorname{Hom}(\Delta^3, M_W) \),  
we need to construct $\tilde{\psi}_2(\langle 013 \rangle)(0,1,2)$ and $\tilde{\psi}_3(\langle 0123 \rangle)(0,1,2,3)$. We construct them as follows:
\begin{align*}
\tilde{\psi}_1(\langle ij \rangle)(0,1) &\coloneqq {\psi}_1(\langle ij \rangle)(0,1) \ {\rm\ for\ all\ 0\le i\le j \le 3}\\
\tilde{\psi}_2(\langle 012 \rangle)(0,1,2) &\coloneqq {\psi}_2(\langle 012 \rangle)(0,1,2) \\
\tilde{\psi}_2(\langle 123 \rangle)(0,1,2) &\coloneqq {\psi}_2(\langle 123 \rangle)(0,1,2) \\
\tilde{\psi}_2(\langle 023 \rangle)(0,1,2) &\coloneqq {\psi}_2(\langle 023 \rangle)(0,1,2) \\
\tilde{\psi}_2(\langle 013 \rangle)(0,1,2) &\coloneqq h_{023}{^{g_{23}}}h_{012}h^{-1}_{234}\\
\tilde{\psi}_3(\langle 0123 \rangle)(0,1,2,3) &\coloneqq e_L.
\end{align*}




Here, we write \( g_{ij} \) and \( h_{ijk} \) as follows:
\begin{align*}
g_{ij}&\coloneqq \psi_1(\langle ij \rangle)(0,1)\\
h_{ijk}&\coloneqq \psi_2(\langle ijk \rangle)(0,1,2).
\end{align*}

\item ${\rm Hom}(\Lambda^4_i, M_W)$ to ${\rm Hom}(\Delta^4, M_W)$ for $1 \le i \le 3$

We will prove the case \( i = 3 \). The cases \( i = 1, 2 \) can be handled in a similar manner.
The difference between \( \Lambda^4_3 \) and \( \Delta^4 \) is the presence of the 3-simplex \( \langle 0124 \rangle \) and the 4-simplex \( \langle 01234 \rangle \).
By the properties of \( M_W \), to extend \( \psi \in \operatorname{Hom}(\Lambda^4_3, M_W) \) to  
\( \tilde{\psi} \in \operatorname{Hom}(\Delta^4, M_W) \),  
it suffices to construct only  $\tilde{\psi}_3(\langle 0124 \rangle)(0,1,2,3)$.
The following construction will be sufficient:  
\begin{align*}
\tilde{\psi}_1(\langle ij \rangle)(0,1) &\coloneqq {\psi}_1(\langle ij \rangle)(0,1)  \text{ for all } 0\le i\le j \le 3,\\
\tilde{\psi}_2(\langle ijk \rangle)(0,1,2) &\coloneqq {\psi}_2(\langle ijk \rangle)(0,1,2)  \text{ for all }  0\le i\le j \le k\le 4,\\
\tilde{\psi}_3(\langle 1234 \rangle)(0,1,2) &\coloneqq {\psi}_3(\langle 1234 \rangle)(0,1,2),\\
\tilde{\psi}_3(\langle 0234 \rangle)(0,1,2) &\coloneqq {\psi}_3(\langle 0234 \rangle)(0,1,2),\\
\tilde{\psi}_3(\langle 0134 \rangle)(0,1,2) &\coloneqq {\psi}_3(\langle 0134 \rangle)(0,1,2),\\
\tilde{\psi}_3(\langle 0123 \rangle)(0,1,2) &\coloneqq {\psi}_3(\langle 0123 \rangle)(0,1,2), \text{ and }\\
\tilde{\psi}_3(\langle 0123 \rangle)(0,1,2) &\coloneqq {}^{h_{014}} l_{1234} \, l_{0134} \, {}^{h_{034}}\left( {}^{g_{34}} l_{0123}\right) \, l^{-1}_{0234} \, {}^{h_{024}} \{ h_{234}, {}^{g_{34} g_{23}} h_{012} \}.
\end{align*}
Here, we write \( g_{ij} \), \( h_{ijk} \), and \( l_{ijkm} \)  as follows: 
\begin{align*}
g_{ij}&\coloneqq \psi_1(\langle ij \rangle)(0,1),\\
h_{ijk}&\coloneqq \psi_2(\langle ijk \rangle)(0,1,2), \text{ and}\\
l_{ijkm}&\coloneqq \psi_3(\langle ijkm \rangle)(0,1,2,3).
\end{align*}

\item ${\rm Hom}(\Lambda^n_i, M_W)$ to ${\rm Hom}(\Delta^n, M_W)$ for $5\le n$ and $1 \le i \le n-1$

The difference between \( \Lambda^n_i \) and \( \Delta^n \) is the presence or absence of the \((n-1)\)-simplex \( \langle 01 \dots \hat{i} \dots n \rangle \) and the \( n \)-simplex \( \langle 01 \dots n \rangle \).
By the properties of \( M_W \), any \( \psi \in \operatorname{Hom}(\Lambda^n_i, M_W) \) can be extended directly to  
\( \tilde{\psi} \in \operatorname{Hom}(\Delta^n, M_W) \) as follows:
\begin{align*}
\tilde{\psi}_1(\langle ij \rangle)(0,1) &\coloneqq {\psi}_1(\langle ij \rangle)(0,1)  \text{ for all }  0\le i\le j \le 3, \\
\tilde{\psi}_2(\langle ijk \rangle)(0,1,2) &\coloneqq {\psi}_2(\langle ijk \rangle)(0,1,2)  \text{ for  all } 0\le i\le j \le k\le 4, \text{ and}\\
\tilde{\psi}_3(\langle ijkm \rangle)(0,1,2,3) &\coloneqq {\psi}_3(\langle ijkm \rangle)(0,1,2,3) \text{ for all } 0\le i\le j \le k\le m \le n.
\end{align*}
\end{enumerate}
This completes the proof.
\end{proof}

\label{sec-3-crossed module and sset}

In this section, we define a 3-crossed module. After defining the notion of a 3-crossed module, we construct a simplicial set associated with it and prove that this simplicial set is a quasi-category.

A 3-crossed module involves four distinct groups, four types of actions, and six types of liftings.

\begin{dfn}{(3-crossed module)}
\label{d3cm}
Let $G,H,L,M$ be groups. A {\bf 3-crossed module} is a complex of groups:
\[
 M\xrightarrow{\partial}L \xrightarrow{\partial} H \xrightarrow{\partial} G 
\]
together with the following structures:
\begin{itemize}
  \item a left action of $G$ by automorphisms on  $H$, $L$ and $M$ (with the action on $G$ given by conjugation),
  \item a left action of $H$ by automorphisms on $L$ and $M$ (with the action on $H$ also given by conjugation),
  \item a left action of $L$ by automorphisms on $M$(with the action on $L$ also given by conjugation),
  \item a function $\{-,-\} : H \times H \rightarrow L$ (called the Peiffer lifting),
  \item a function $\{-,-,-\} : H \times H \times H  \rightarrow M$ (called the Left-Homanian),
  \item a function $\{-,-,-\}' : H \times H \times H  \rightarrow M$ (called the Right-Homanian),
  \item a function $\{-,-\}_{HL} : H \times L \rightarrow M$ (called the HL-Peiffer lifting),
  \item a function $\{-,-\}'_{HL} : H \times L \rightarrow M$ (called the HL'-Peiffer lifting),  and
  \item a function $\{-,-\}_{LL} : L \times L \rightarrow M$ (called the LL-Peiffer lifting),         
\end{itemize}
which are required to satisfy the following axioms:
\begin{enumerate}
  \item Each $\partial$ is homomorphism.
  \item  $\partial\circ \partial =0$.
  \item For each $g \in G$, $h \in H$, $l \in L$, and $m \in M$,
  \begin{align*}
\left\{
    \begin{aligned}
    & \partial({}^gh)= {{}^g}\partial(h) \\
