 \{h_4h_3,h_2,h_1\}\act{\left(\act{h_4h_3}\{h_2,h_1\}\right)}\{h_4,h_3,\act{\partial h_2}h_1\} = \{h_4,h_3h_2,h_1\}\act{h_4}\{h_3,h_2,h_1\} .
 \]
