\{h_4,h_3h_2,h_1\}'\{h_4,h_3,h_2\}' = \{h_4,h_3,h_2h_1\}'\act{\{h_4,h_3\}}(\act{\left(\act{\partial h_4}h_3\right)}\{h_4,h_2,h_1\}') .
 \]
 \label{rhmnr}

    \item For each $h_1,h_2,h_3,h_4 \in H$,
 \begin{align*}
&\{h_4,h_3,h_2h_1\}\act{\left(\act{h_4}\{h_3,h_2h_1\}\right)}\{h_4,\act{\partial h_3}h_2,\act{\partial h_3}h_1\}'\act{h_4}\{h_3,h_2,h_1\}' \\
  &= \{h_4h_3,h_2,h_1\}'\act{\{h_4h_3,h_2\}}(\act{\act{\partial (h_4h_3)}h_2}\{h_4,h_3,h_1\})\{h_4,h_3,h_2\} \\
   &\hspace{1em}\times\act{\left(\act{h_4}\{h_3,h_2\}\right)}\{\{h_4,\act{\partial h_3}h_2\},\act{\left(\act{\partial(h_4h_3)}h_2h_4\right)}\{h_3,h_1\}\}_{LL}.
