 \label{lrhmnr}
 

  \item For each $h_1,h_2,h_3 \in H$,
  \label{yanBt}
 \begin{align}
  \nonumber
 &\act{\act{h_3}\{h_2,h_1\}}(\{h_3,\act{\partial h_2}h_1,h_2\}'^{-1}\{h_3,\partial\{h_2,h_1\}^{-1},h_2h_1\}')\{h_3,\{h_2,h_1\}\}' \\
  \nonumber
  \hspace{1em} &\{\act{\partial h_3}\{h_2,h_1\},\act{\partial\act{\partial h_3}\{h_2,h_1\}^{-1}}\{h_3,h_2h_1\}\}\{h_3,h_2,h_1\}' \\
  \nonumber
  &= \{h_3,h_2,h_1\}^{-1}\act{\{h_3h_2,h_1\}}\{\act{\partial(h_3h_2)}h_1,\{h_3,h_2\}\}^{-1}\{\{h_3,h_2\},\act{\partial\{h_3,h_2\}^{-1}}\{h_3h_2,h_1\}\}^{-1} \\
  \nonumber
  &\hspace{1em} \act{\{h_3,h_2\}}(\{\partial\{h_3,h_2\}^{-1},h_3h_2,h_1\}^{-1}\{\act{\partial h_3}h_2,h_3,h_1\})
\end{align}
 
 
 

 
 
 
    \item For each $l,l' \in L$,
