    \act{l}\{\partial l',l^{-1}\}_{HL}\act{ll'l^{-1}l'^{-1}}\{l',l\}_{LL}= \act{\left(\act{\partial l}l'\right)}\{\partial l,l'^{-1}\}'_{HL}\{l,l'\}^{-1}_{LL}.
    \]
     \item For each $l\in L$ and $m \in M$,
    \[
    \{\partial m,l\}_{LL}\{l,\partial m\}_{LL} = \{\partial l,\partial m\}_{HL} = \{\partial l,\partial m\}'^{-1}_{HL}.
