\begin{rem}
Properties \ref{rllandhl} and \ref{3cm_not_need} can be derived from the other axioms of a 3-crossed module. Specifically, property \ref{rllandhl} is obtained by applying properties \ref{act_u_ll_dellm} and \ref{act_u_ll_lm} to the term $\act{\del l}m$, along with property \ref{act_h_m_3cm} in $\act{\del l}m$ and property \ref{dhmnl} in $\act{\del \circ \del l}m$. Similarly, property \ref{3cm_not_need} follows from properties \ref{act_u_ll_lm} and \ref{act_delm_m_3cm} applied to $\act{\del m'}m$. We include these properties explicitly for the reader's convenience.
\end{rem}

There are six types of liftings. One is the normal Peiffer lifting. The LL-Peiffer lifting corresponds to the normal Peiffer lifting for the complex of groups \( M \xrightarrow{\partial} L \xrightarrow{\partial} H \).
The HL-Peiffer lifting, HL'-Peiffer lifting, and the left and right Homanian are new types of liftings that arise specifically in 3-crossed modules.
As can be seen in the 3-crossed module property~\ref{dhl}, the HL-Peiffer lifting is a twisted version of the 2-crossed module property~\ref{acthl}. According to the 3-crossed module property~\ref{dhlp}, the HL'-Peiffer lifting is a twist of the 2-crossed module property~\ref{actgl}.
The left Homanian corresponds to a twist of the relation in the 2-crossed module property~\ref{lpl}, while the right Homanian corresponds to a twist of the relation in property~\ref{rpl}.

Some of the relations in a 3-crossed module can be understood through diagrams that can be described in the language of category theory.  
See Appendix~\ref{app_dia_3cm} for details.


We investigate the behavior of liftings when one of the arguments is the unit element.
The following lemma describes this situation.
\begin{lemma}
\label{lemma_of_unit_element}
Let $G,H,L,M$ be groups, and let
$
 M\xrightarrow{\partial}L \xrightarrow{\partial} H \xrightarrow{\partial} G 
$ be 3-crossed module. Then the six types of liftings satisfy the following equations:
\begin{align}
\{h_2, h_1\}
  &= e_L
  && \text{if $h_2 = e_H$ or $h_1 = e_H$,}
  \label{eq:einpl} \\
 \{l_2, l_1\}
  &= e_M
  && \text{if $l_2 = e_L$ or $l_1 = e_L$,}
  \label{eq:einll} \\
\{h_3, h_2, h_1\}
  &= \{h_3, h_2, h_1\}' = e_M
  && \text{if $h_3 = e_H$ or $h_2 = e_H$ or $h_1 = e_H$,}
  \label{eq:einhmn} \\
\{h, l\}_{HL}
  &= \{h, l\}'_{HL} = e_M
  && \text{if $h = e_H$ or $l = e_L$.}
  \label{eq:einhl}
\end{align}
Here, $e_X$ denotes the unit element of the group $X$. 
\end{lemma}
\begin{proof}
Equation~(\ref{eq:einll}) follows from Properties \ref{lll} and \ref{rll} of a 3-crossed module applied to $\{e_L e_L, l\}_{LL}$ and $\{l, e_L e_L\}_{LL}$. Indeed,
\begin{equation}
\begin{aligned}
\{e_L e_L , l\}_{LL} &= \{e_L  , l\}_{LL}\{e_L , l\}_{LL},\\
\{l, e_L e_L \}_{LL} &= \{l, e_L\}_{LL} \{l, e_L\}_{LL}.
\end{aligned}
\label{p_einll}
\end{equation}

We next show that, for each $h\in H$,
\begin{equation}
\begin{aligned}
\{e_H, e_H, h\} = e_M,\\
\{h, e_H, e_H\}' = e_M.
\label{hyp_of_unit}
\end{aligned}
\end{equation}
Equation~(\ref{hyp_of_unit}) is obtained by computing $\act{h}(mm')$ and $\act{\del h}(mm')$ and then setting $m=m'=e_M$. We compute $\act{h}(mm')$ as follows:
\begin{align}
  \nonumber
  \act{h}(mm') &= mm'\{h,\partial (mm')^{-1}\}_{HL} \\
  \nonumber
  &= mm'\act{\partial (mm)'^{-1}}\{e_H,e_H,h\}\act{\partial (mm')^{-1}}\{\partial m,\{e_H,h\}\}_{LL}^{-1}\{h,\partial m'^{-1}\}_{HL}\act{\partial \act{h}m'^{-1}}\{h,\partial m^{-1}\}_{HL} \\
  \nonumber
  &= \{e_H,e_H,h\}\{\partial m,\{e_H,h\}\}_{LL}^{-1}mm'\{h,\partial m'^{-1}\}_{HL}\act{\partial \act{h}m'^{-1}}\{h,\partial m^{-1}\}_{HL} \\
  \label{eq:act_hmm}
  &= \{e_H,e_H,h\}\{\partial m,\{e_H,h\}\}_{LL}^{-1}m\act{h}m'\act{\partial \act{h}m'^{-1}}\{h,\partial m^{-1}\}_{HL} \\
  \nonumber
  &= \{e_H,e_H,h\}\{\partial m,\{e_H,h\}\}_{LL}^{-1}m\{h,\partial m^{-1}\}_{HL}\act{h}m' \\
  \nonumber
  &= \{e_H,e_H,h\}\{\partial m,\{e_H,h\}\}_{LL}^{-1}\act{h}m\act{h}m'.
\end{align}
Similarly, $\act{\del h}(mm')$ can be computed in an analogous manner:
\begin{align}
  \nonumber
  \act{\partial h}(mm') &= \act{h}(mm')\{h,\partial (mm')^{-1}\}_{HL} ' \\
  \nonumber
  &= \act{h}(mm')\act{\partial \act{h}(mm')^{-1}}\{h,e_H,e_H\}'\act{\partial \act{h}m'^{-1}}\{h,\partial m^{-1}\}_{HL} '\act{\partial (\act{h}m'^{-1}\act{\partial h}m^{-1})}\{\partial m,\{h,e_H\}\}_{LL} ^{-1}\{h,\partial m'^{-1}\}_{HL} ' \\
  \nonumber
  &= \{h,e_H,e_H\}'\act{h}m\{h,\partial m^{-1}\}_{HL}'\act{\partial (\act{\partial h}m^{-1})}\{\partial m,\{h,e_H\}\}_{LL}^{-1}\act{h}m'\{h,\partial m'^{-1}\}_{HL}' \\
  \label{eq:act_gmm}
  &= \{h,e_H,e_H\}'\act{\partial h}m\act{\partial (\act{\partial h}m^{-1})}\{\partial m,\{h,e_H\}\}_{LL}^{-1}\act{\partial h}m'.
\end{align}
Using Equations~(\ref{eq:act_hmm}) and~(\ref{eq:act_gmm}), together with $m=m'=e_M$ and Equation~(\ref{eq:einll}), we obtain Equation~(\ref{hyp_of_unit}).

Next, by substituting the unit element appropriately into Properties \ref{dhmnr}-\ref{rrHL} of a 3-crossed module, we obtain Equations~(\ref{eq:P11h1h})-(\ref{eq:h11h1}):
\begin{align}
  \label{eq:P11h1h}
  e_L &= \partial\{e_H,e_H,h\}\{e_H,h\}, \\
  \label{eq:Ph11h1}
  e_L &= \partial\{h,e_H,e_H\}'\{h,e_H\}, \\
  \label{eq:Pl111l}
  e_M &= \act{l}\{\partial l^{-1},e_H,e_H\}'\{e_H,l\}_{HL}, \\
  \label{eq:11hh1}
  e_M &= \{e_H,e_H,h\}\{h,e_L\}_{HL},  \\
  \label{eq:11Pl1l}
  e_M &= \act{l}\{e_H,e_H,\partial l^{-1}\}\{e_H,l\}'_{HL},  \\
  \label{eq:h11h1}
  e_M &= \{h,e_L,e_L\}'\{h,e_L\}'_{HL}. 
\end{align}
Using Equations~(\ref{hyp_of_unit}) and (\ref{eq:P11h1h})-(\ref{eq:h11h1}), we obtain Equations~(\ref{eq:einpl}) and~(\ref{eq:einhl}) . 

Now, by setting $h_3=h_2=h_1=e_H$ and $h_4=h_3=h_2=e_H$ in Proprety~\ref{lhmnr} of 3-crossed module, we obtain Equations~(\ref{2ulhmn1}) and (\ref{2ulhmn2}), respectively:
\begin{align}
\label{2ulhmn1}
\{h, e_H, e_H \} = e_M,\\ 
\label{2ulhmn2}
\{e_H, h, e_H \} = e_M.
\end{align}
Similarly, setting $h_4=h_3=h_2=e_H$ and $h_4=h_2=h_1=e_H$ in Proprety~\ref{rhmnr} of a 3-crossed module yields Equations~(\ref{2urhmn1}) and (\ref{2urhmn2}), respectively:
\begin{align}
\label{2urhmn1}
\{e_H, h, e_H \}' = e_M,\\ 
\label{2urhmn2}
\{e_H, e_H, h \}' = e_M.
\end{align}
Using Equations~(\ref{eq:einpl}), (\ref{eq:einll}), (\ref{eq:einhl}), (\ref{hyp_of_unit}), and (\ref{2ulhmn1})-(\ref{2urhmn2}) where necessary, and applying Property~\ref{lhmnr} of a 3-crossed module with $h_4 = h_3 = e_H$ and with $h_3= h_2 = e_H$, we obtain Equation~(\ref{1ulhmn1}) and (\ref{1ulhmn2}), respectively:
  \begin{align}
\label{1ulhmn1}
\{e_H, h_2, h_1 \} = e_M,\\ 
\label{1ulhmn2}
\{h_4, e_H, h_1 \} = e_M.
\end{align}

Similarly, applying Property~\ref{rhmnr} of a 3-crossed module with $h_3 = h_2 = e_H$ and with $h_2= h_1 = e_H$, we obtain Equation~(\ref{1urhmn1}) and (\ref{1urhmn2}), respectively:
\begin{align}
\label{1urhmn1}
\{h_4, e_H, h_1 \}' = e_M,\\ 
\label{1urhmn2}
\{h_4, h_3, e_H \}' = e_M.
\end{align}

Finaly, applying Property~\ref{lrhmnr} of a 3-crossed module with $h_2 = h_1 = e_H$ and with $h_4= h_3 = e_H$, we obtain Equation~(\ref{1ulhmn3}) and (\ref{1urhmn3}), respectively:
\begin{align}
\label{1ulhmn3}
\{h_4, h_3, e_H \} = e_M,\\ 
\label{1urhmn3}
\{e_H, h_2, h_1 \}' = e_M.
\end{align}
This completes the proof.

\end{proof}


These twists naturally appear in the simplicial set associated with a 3-crossed module.  
We now construct the simplicial set associated with a 3-crossed module. This can be done by adding additional structure to the simplicial set associated with a 2-crossed module.

Let \( T \coloneqq  (M \xrightarrow{\partial} L \xrightarrow{\partial} H \xrightarrow{\partial} G) \) be a 3-crossed module.  
The simplicial set \( M_T \) associated with this 3-crossed module consists of the following data:



\begin{itemize}
    \item For each $[n] \in \Delta$, the set $M_W([n])$ consists of quadruples 
    \[ (g(-,-), h(-,-,-), l(-,-,-,-),m(-,-,-,-,-)) ,\]
    where:
    \begin{enumerate}
        \item $g: [n] \times_{\le} [n] \to G$ is a function assigning each ordered pair in $[n]$ to an element of $G$,
        \item $h: [n] \times_{\le} [n] \times_{\le} [n] \to H$ is a function assigning each ordered triple in $[n]$ to an element of $H$,  
        \item $l: [n] \times_{\le} [n] \times_{\le} [n] \times_{\le} [n] \to L$ is a function assigning each ordered quadruple in $[n]$ to an element of $L$, and
        \item $m: [n] \times_{\le} [n] \times_{\le} [n] \times_{\le} [n] \times_{\le} [n] \to M$ is a function assigning each ordered quintuple in $[n]$ to an element of $M$,
    \end{enumerate}
    satisfying the following conditions:
    
	
\begin{enumerate}[label=(\alph*)]
\item for each $i \le j \le k$ in $[n]$, we have the idenntity 
\begin{equation}
g_{ik} = \partial(h_{ijk})g_{jk}g_{ij},
\label{r2-simplex m}
\end{equation}
\item for each $i \le j \le k \le p$ in $[n]$, we have the identity 
\begin{equation}
\partial (l_{ijkp})  h_{ikp}{^{g_{kp}}}h_{ijk} = h_{ijp}h_{jkp},
\label{r3-simplex m}
\end{equation}
\item for each $i \le j \le k \le p \le q$ in $[n]$, we have the idenntity 
\begin{equation}
 \partial(m_{ijkpq}) {^{h_{ijq}}}l_{jkpq}l_{ijpq}{^{h_{ipq}}}\left({^{g_{pq}}}l_{ijkp}\right) = l_{ijkq}{^{h_{ikq}}}\{h_{kpq},{^{g_{pq}g_{kq}}}h_{ijk} \}^{-1}l_{ikpq} ,
\label{r4-simplex m}
\end{equation}
\item for each $i \le j \le k  \le p \le q\le x$ in $[n]$, we have the idenntity 

\label{r5-simplex m}
\begin{equation}
\label{r5-simplex m:eq}
\begin{aligned}
   \act{L_D L_E}M_5 \cdot \act{L_D L_E L_F}M_4 &\cdot M_3 \cdot \act{L_A}M_2 \cdot  \act{L_A L_B L_C} M_1\\
   =
   \act{}M'_{13}
   &\cdot \act{L_K L_N}M'_{12}
   \cdot \act{L_K }M'_{11}
   \cdot \act{L_K L_L}M'_{10}
   \cdot \act{L_K L_L L_M}M'_9\\
  & \cdot \act{}M'_8 
   \cdot \act{L_G L'_I}M'_7
   \cdot \act{L_G L'_I}M'_6
   \cdot \act{L_G }M'_5\\
   &\cdot \act{L_G L_H L_I L_J}M'_4
   \cdot \act{L_G L_H}M'_3
   \cdot \act{}M'_2
   \cdot \act{L_A L_B}M'_1.
   \end{aligned}
   \end{equation}

Here each term will be written as follows:

\noindent
\begin{align*}
     L_A &= \act{h_{ijx}h_{jkx}}l_{kpqx}\\
   L_B &= \act{h_{ijx}}l_{jkqx}\\
   L_C &=l_{ijqx}\\
   L_D &=l_{ijkx}\\
   L_E &=\act{h_{ikx}(\act{g_{kx}}h_{ijk})}l_{kpqx}\\
   L_F &=\act{h_{ikq}}\{h_{kqx}, \act{g_{qx}g_{kq}}h_{ijk} \}^{-1}\\
   M_j &= \act{h_{iqx}}\left(\act{g_{qx}}m_{ijkpq} \right)\\
   M_k &= m_{ijkqx}\\
