.\]
\end{itemize}



The simplicial set associated with a 3-crossed module is also a quasi-category.  
The proof is similar to the proof for the simplicial set associated with a 2-crossed module.
With a slight extension, the argument of Lemma~\ref{lemma1} also applies to \( M_T \).

\begin{lemma}
\label{lemma1_3cm}
Let \( T \coloneqq (M \xrightarrow{\partial} L \xrightarrow{\partial} H \xrightarrow{\partial} G \) be a 3-crossed module. For any \( n \ge 1 \) and any inner horn \( \Lambda^n_j \), let \( \phi \in \operatorname{Hom}(\Lambda^n_j, M_W) \). Then, for any \( k \ge 1 \) and any \( f \in (\Lambda^n_j)_k \), the following identity holds:
\[
\phi_k(f) 
\coloneqq
\begin{pmatrix}
\phi^g_k(f)(-,-) \\
\phi^h_k(f)(-,-,-) \\
\phi^l_k(f)(-,-,-,-)\\
\phi^m_k(f)(-,-,-,-,-)
\end{pmatrix}
=
\begin{pmatrix}
\phi^g_1(f(-,-))(0,1) \\
\phi^h_2(f(-,-,-))(0,1,2) \\
\phi^l_3(f(-,-,-,-))(0,1,2,3)\\
\phi^m_4(f(-,-,-,-))(0,1,2,3,4)
\end{pmatrix}.
\]
\end{lemma}
\begin{proof}
The proof is similar to that of Lemma~\ref{lemma1}.
\end{proof}

By using Lemmas~\ref{lemma2} and~\ref{lemma1_3cm}, we can prove $M_T$ is quasi-category in similar way of $M_S$.

\begin{theorem}
Let \( T \coloneqq (M \xrightarrow{\partial} L \xrightarrow{\partial} H \xrightarrow{\partial} G, \{-,-\}) \) be a 3-crossed module. Then the simplicial set $M_T$ is a quasi-category.
\end{theorem}
\begin{proof}
The proof is essentially the same as that of Theorem~\ref{2cm and qusi}.
\end{proof}

In this section, we will give a way to construct a 3-crossed module from a 2-crossed module. This is a standard construction, and an extension of the well-known methods for obtaining a crossed module from a group or a 2-crossed module from a crossed module.

Let $C\xrightarrow{\partial}B \xrightarrow{\partial} A$ be a 2-crossed module. We will set the groups $G,H,L$ and $M$ as follows:
\[
G \coloneqq A, \quad H \coloneqq B\times A, \quad L \coloneqq C\times B, \quad M \coloneqq C.
\]
For $G$ and $M$, the group product is that of $A$ and $C$, respectively. For $H$ and $L$, the group product is defined component-wise; i.e., for $h_2=(b_2, a_2), h_1=(b_1, a_1) \in H$ and $l_2=(c_2, b_2), l_1=(c_1, b_1) \in l$, we define the group products $h_2 \cdot_H h_1$ and $l_2 \cdot_L l_1$ as following:
\begin{equation}
\label{ex2:prod}
\begin{aligned}
h_2 \cdot_H h_1 &\coloneqq (b_2 \cdot_B b_1, a_2 \cdot_A a_1), \\
l_2 \cdot_L l_1 &\coloneqq (c_2 \cdot_C c_1, b_2 \cdot_B b_1).
\end{aligned}
\end{equation}

We define the maps $\del:M \rightarrow L, \del:L \rightarrow H$ and $\del:H \rightarrow G$ as follows:
\begin{equation}
\label{ex2:del}
\begin{aligned}
\del : &M \longrightarrow L\\
   &c  \longmapsto (c, e_B), \\
\del : &L \longrightarrow H\\
   &(c,b)  \longmapsto (b, e_A),\\
\del : &H \longrightarrow G\\
   &(b,a)  \longmapsto a.         
\end{aligned}
\end{equation}
Here, $e_X$ denotes the identity element in the group $X$.

To equip this sequence with the structure of a 3-crossed module, we must define the required actions and six types of liftings. We define these as follows.

\textbf{Actions.}

The actions are derived from the 2-crossed module structure. Let $g=a_g \in G, h=(b_h, a_h) \in H, l=(c_l, b_l) \in L,$ and $m = c_m \in M$. We define:
\begin{equation}
\begin{aligned}
  \act{g}h &\coloneqq  (\act{a_g}b_h,\act{a_g}a_h), & \act{g}l &\coloneqq  (\act{a_g}c_l,\act{a_g}b_l), & \act{g}m &\coloneqq  \act{a_g}c_m, \\
  && \act{h}l &\coloneqq  (\act{b_h}c_l,\act{b_g}b_l), & \act{h}m &\coloneqq  \act{b_h}c_m, \\
  &&&& \act{l}m &\coloneqq  \act{c_l}c_m.
\end{aligned}
\end{equation}


\textbf{Peiffer lifting.}

Since $C\xrightarrow{\partial}B \xrightarrow{\partial} A$ is a 2-crossed module, it is equipped with a Peiffer lifting, which we denote $\{-,-\}_B : B \times B \to C$. We define the new Peiffer lifting $\{-,-\} : H \times H \to L$ using this. For $h_1=(b_1, a_1)$ and $h_2=(b_2, a_2)$ in $H$, we define:
\begin{align}
\{h_2, h_1\} \coloneqq (\{b_2, b_1\}_B, b_2b_1b_2^{-1} \act{a_1}b_1^{-1} ).
\end{align}


\textbf{Left-Homanian.}

We define the Left-Homanian $\{-, -, -\} : H \times H \times H \to M$ using the 2-crossed module's lifting $\{-,-\}_B$.  For $h_3 = (b_3, a_3), h_2 = (b_2, a_2), h_1 = (b_1, a_1) \in H$, it is defined as:
\begin{align}
\label{ex_lhmn}
\{h_3,h_2,h_1\} \coloneqq \{b_3b_2,b_1\}_B\{b_3,\act{a_2}b_1\}_B^{-1}\act{b_3}\{b_2,b_1\}_B^{-1}.
\end{align}
This expression is related to the 2-crossed module axiom (Property~\ref{lpl}). If $a_2 = \del (b_2)$ were satisfied, the right-hand side would equal $e_C$ by that property. However, in $H = B \times A$, $a_2$ is not necessarily equal to $\del(b_2)$, so this lifting is not generally trivial.



\textbf{Right-Homanian.}

 The Right-Homanian is defined in a similar manner. For $h_3 = (b_3, a_3), h_2 = (b_2, a_2), h_1 = (b_1, a_1) \in H$:
\begin{align}
\label{ex_rhmn}
\{h_3,h_2,h_1\}' \coloneqq \{b_3,b_2b_1\}_B\act{(\act{a_3}b_2)}\{b_3,b_1\}_B^{-1}\{b_3,b_2\}_B^{-1}.
\end{align}


\textbf{HL-Peiffer lifting.}

This lifting $\{-,-\}_{HL} : H \times L \to M$ is defined as:
For $l_1 = (c_1, b_1) \in L$ and $h_2 = (b_2, a_2) \in H$,
\begin{align}
\{h_2,l_1\}_{HL} \coloneqq c_1\{b_1^{-1},b_2\}_B\act{b_2}c_1^{-1}.
\end{align}


\textbf{HL'-Peiffer lifting.}

This lifting $\{-,-\}'_{HL} : H \times L \to M$ is defined as:
For $l_1 = (c_1, b_1) \in L$ and $h_2 = (b_2, a_2) \in H$,
\begin{align}
\{h_2,l_1\}'_{HL} = \act{b_2}c_1\{b_2,b_1^{-1}\}_B\act{a_2}c_1^{-1}.
\end{align}


\textbf{LL-Peiffer lifting.}

This lifting $\{-,-\} : L \times L \to M$ is defined as:
For $l_1 = (c_1, b_1), l_2 = (c_2, b_2)  \in L$,
\begin{align}
\label{ex2:ll}
\{l_2,l_1\}_{LL} = c_2 c_1 c_2^{-1}\act{b_2}c_1^{-1}.
\end{align}

With equations~(\ref{ex2:prod})through~(\ref{ex2:ll}), we have defined all structures required for a 3-crossed module: the groups, maps, actions, and six types of liftings. The remaining work is to prove that these definitions satisfy all the axioms of a 3-crossed module. These structures do indeed satisfy the axioms, leading to the following theorem:

\begin{theorem}
Let $C\xrightarrow{\partial}B \xrightarrow{\partial} A$ be a 2-crossed module. Let $G \coloneqq A$, $H \coloneqq B\times A$, $L \coloneqq C\times B$, and $M \coloneqq C$, with group structures as defined in \eqref{ex2:prod}.
Then $M \xrightarrow{\partial} L \xrightarrow{\partial} H \xrightarrow{\partial} G$ forms a 3-crossed module with the maps, actions, and liftings defined in \eqref{ex2:del} through \eqref{ex2:ll}.
\end{theorem}
\begin{proof}
The proof consists of checking all the properties of a 3-crossed module. This is a straightforward but lengthy calculation.

As an example, we will show that this structure satisfies the 3-crossed module axiom for Property~\ref{rl:hhl}. Property~\ref{rl:hhl} is as follows: for $h_1 = (b_1, a_1), h_2 = (b_2, a_2)  \in H$ and $l = (c_l, b_l) \in L$,
\begin{align*}
\{h_2h_1,l\}_{HL} = \act{l}\{\partial l^{-1},h_2,h_1\}'\{h_2,l\}_{HL} \act{h_2}\{h_1,l\}_{HL}  .
\end{align*}
We can show this holds by the following calculation:
\begin{align*}
  \nonumber
  (\text{LHS}) &= \{(b_2,a_2)(b_1,a_1),(c_l,b_l)\}_{HL} \\
  \nonumber
  &= \{(b_2b_1,a_2a_1),(c_l,b_l)\}_{HL} \\
  \nonumber
  &= c_l\{b_l^{-1},b_2b_1\}\act{b_2b_1}c_l^{-1} \\
  \nonumber
  (\text{RHS}) &= \act{(c_l,b_l)}\{\partial (c_l,b_l)^{-1},(b_2,a_2),(b_1,a_1)\}'\{(b_2,a_2),(c_l,b_l)\}_{HL}\act{(b_2,a_2)}\{(b_1,a_1),(c_l,b_l)\}_{HL} \\
  \nonumber
  &= \act{(c_l,b_l)}\{(b_l^{-1},e_A),(b_2,a_2),(b_1,a_1)\}'c_l\{b_l^{-1},b_2\}\act{b_2}c_l^{-1}\act{(b_2,a_2)}(c_l\{b_l^{-1},b_1\}\act{b_1}c_l^{-1}) \\
  \nonumber
  &= \act{(c_l,b_l)}(\{b_l^{-1},b_2b_1\}\act{b_2}\{b_l^{-1},b_1\}^{-1}\{b_l^{-1},b_2\}^{-1})c_l\{b_l^{-1},b_2\}\act{b_2}c_l^{-1}\act{b_2}c_l\act{b_2}\{b_l^{-1},b_1\}\act{b_2b_1}c_l^{-1} \\
  &= c_l(\{b_l^{-1},b_2b_1\}\act{b_2}\{b_l^{-1},b_1\}^{-1}\{b_l^{-1},b_2\}^{-1})c_l^{-1}c_l\{b_l^{-1},b_2\}\act{b_2}c_l^{-1}\act{b_2}c_l\act{b_2}\{b_l^{-1},b_1\}\act{b_2b_1}c_l^{-1} \\
  \nonumber
  &= c_l\{b_l^{-1},b_2b_1\}\act{b_2b_1}c_l^{-1} = (\text{LHS})
\end{align*}
The other properties of a 3-crossed module can be verified in a similar manner.
\end{proof}

